// Newton's method for F(X) = 0
// Initialize
X = X0;
k = 0;

while (norm(F(X)) > tol && k < kmax) {
  // 1. Build Jacobian at current X
  J = jacobian(F, X);

  // 2. Solve linear system (Gauss / LU / QR) — do NOT invert J
  Delta = solve(J, -F(X));

  // 3. Update
  X = X + Delta;
  k = k + 1;
}

// Aitken's scheme — full 2D table
for (i = 0; i <= n; i++) dd[i][0] = y[i];

for (k = 1; k <= n; k++)
  for (i = 0; i <= n - k; i++)
    dd[i][k] = (dd[i + 1][k - 1] - dd[i][k - 1]) / (x[i + k] - x[i]);

// Coefficients of Newton form: dd[0][0], dd[0][1], ..., dd[0][n]

// Aitken's scheme — in place, one vector
for (k = 1; k <= n; k++)
  for (i = n; i >= k; i--)
    y[i] = (y[i] - y[i - 1]) / (x[i] - x[i - k]);

// After this loop: y[k] == [x_0, x_1, ..., x_k]_f for k = 0..n
// These are exactly the Newton form coefficients.

